describe('Profile Picture Upload and Preview', () => {
  beforeEach(() => {
    cy.visit('/profile');
  });

  it('should successfully upload a profile picture and display preview', () => {
    // Intercept the API call for uploading the image
    cy.intercept('POST', '/api/profile/upload', {
      statusCode: 200,
      body: {
        id: '12345',
        url: 'https://example.com/profile/12345.jpg',
        size: 1024,
        mimeType: 'image/jpeg'
      }
    }).as('uploadProfilePicture');

    // Get the upload button and file input
    cy.get('[data-testid="upload-picture-btn"]').click();
    cy.get('[data-testid="profile-picture-input"]').selectFile('cypress/fixtures/test-image.jpg', {
      force: true
    });

    // Verify the file is selected
    cy.get('[data-testid="file-name-display"]').should('contain', 'test-image.jpg');

    // Verify the preview appears
    cy.get('[data-testid="preview-image"]').should('be.visible');
    cy.get('[data-testid="preview-image"]').should('have.attr', 'src', 'data:image/jpeg;base64,...');

    // Verify the preview image is displayed
    cy.get('[data-testid="preview-image"]').should('have.css', 'width', '100px');
    cy.get('[data-testid="preview-image"]').should('have.css', 'height', '100px');

    // Verify the upload button is disabled after selection
    cy.get('[data-testid="upload-picture-btn"]').should('be.disabled');

    // Verify the success message appears
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Profile picture uploaded successfully');

    // Verify the API call was made
    cy.wait('@uploadProfilePicture');
  });

  it('should handle invalid file type and display error message', () => {
    // Intercept the API call for uploading the image
    cy.intercept('POST', '/api/profile/upload', {
      statusCode: 400,
      body: {
        error: 'Invalid file type'
      }
    }).as('uploadProfilePictureError');

    // Get the upload button and file input
    cy.get('[data-testid="upload-picture-btn"]').click();
    cy.get('[data-testid="profile-picture-input"]').selectFile('cypress/fixtures/invalid-file.txt', {
      force: true
    });

    // Verify the file is selected
    cy.get('[data-testid="file-name-display"]').should('contain', 'invalid-file.txt');

    // Verify the preview does not appear
    cy.get('[data-testid="preview-image"]').should('not.exist');

    // Verify the error message appears
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Invalid file type');

    // Verify the upload button is still enabled
    cy.get('[data-testid="upload-picture-btn"]').should('not.be.disabled');

    // Verify the API call was made
    cy.wait('@uploadProfilePictureError');
  });
});
